mapper.sql:
SELECT c.id, c.name, c.image, CASE WHEN c.background IS NOT NULL AND c.background != '' THEN c.background ELSE c.appearance END AS intro, COALESCE(fc.follow_count, 0) AS follow_count, CASE WHEN uf.follow_id IS NULL THEN FALSE ELSE TRUE END AS is_followed, c.create_time FROM app_character c LEFT JOIN ( SELECT character_id, COUNT(*) AS follow_count FROM user_follow_character WHERE status = 1 GROUP BY character_id ) fc ON fc.character_id = c.id LEFT JOIN user_follow_character uf ON uf.character_id = c.id AND uf.status = 1
AND uf.user_id = #{userId}
AND 1 = 0
